<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/**
 * CRM admin interface (Phase 6): sign-in gate, action controller and views. Everything is behind crm_gate(); every POST needs the session CSRF
 * token and a same-origin request; every action is permission-checked again inside the library functions.
 */
require_once __DIR__ . '/crm_intake.php';

function crm_h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES); }
function crm_gate_page(string $title, string $body, int $status = 200): void {
  http_response_code($status); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex, nofollow');
  $GLOBALS['title'] = $title . ' — AIHubpedia CRM'; $robots = 'noindex, nofollow'; /* local variable: this function includes the layout, which reads $robots from the including scope */ require __DIR__ . '/layout_top.php'; echo '<section class="panel" style="max-width:520px;margin:24px auto">' . $body . '</section>'; require __DIR__ . '/layout_bottom.php'; exit;
}
/** Gate: returns the signed-in user, or renders the sign-in form / a disabled notice and exits. Must run before any output. */
function crm_gate(): array {
  header('Cache-Control: no-store'); header('X-Robots-Tag: noindex, nofollow');
  if (!crm_tables_ready()) crm_gate_page('CRM unavailable', '<h1 style="margin-top:0">CRM is not set up</h1><p class="small">The CRM tables are not installed on this server. Apply <code>database/phase6_crm.sql</code> to an isolated or reviewed database first.</p>', 503);
  $pdo = crm_pdo();
  if ((int)$pdo->query('SELECT COUNT(*) FROM crm_users WHERE active = 1')->fetchColumn() === 0) crm_gate_page('CRM disabled', '<h1 style="margin-top:0">CRM is disabled</h1><p class="small">No CRM user exists. Create one from the command line with <code>php scripts/crm_user.php</code>. There are no default accounts.</p>', 503);
  $msg = '';
  if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && ($_POST['act'] ?? '') === 'login') {
    if (!sec_same_origin() || !sec_token_valid((string)($_POST['_login_token'] ?? ''), 'crm-login', 1)) $msg = 'Please reload the page and try again.';
    else { [$code] = crm_login($pdo, (string)($_POST['username'] ?? ''), (string)($_POST['password'] ?? '')); if ($code === 'ok') { header('Location: ' . sec_safe_local_path($_SERVER['REQUEST_URI'] ?? '/crm.php', '/crm.php'), true, 303); exit; } if ($code === 'rate_limited') http_response_code(429); $msg = $code === 'rate_limited' ? 'Too many attempts. Try again in 15 minutes.' : 'Sign-in failed.'; }
  }
  $u = crm_current_user($pdo); if ($u) return $u;
  crm_gate_page('CRM sign-in', '<h1 style="margin-top:0">CRM sign-in</h1>' . ($msg !== '' ? '<div class="noteBox" role="alert">' . crm_h($msg) . '</div>' : '') . '<form method="post" autocomplete="off"><input type="hidden" name="act" value="login"><input type="hidden" name="_login_token" value="' . crm_h(sec_token('crm-login')) . '">'
    . '<label for="crmUser">Username</label><input class="input" id="crmUser" name="username" autocomplete="username" required><label for="crmPw">Password</label><input class="input" id="crmPw" name="password" type="password" autocomplete="current-password" required><p style="margin-top:14px"><button class="btn">Sign in</button></p></form>', http_response_code() === 429 ? 429 : 200);
  return [];
}

// ---- form helpers --------------------------------------------------------------------------------------------------------------------
function crm_f_input(string $name, string $label, string $val = '', string $type = 'text', string $attrs = ''): string { $id = 'f_' . preg_replace('/\W+/', '_', $name) . '_' . substr(md5($label . $attrs), 0, 4); return '<div class="field"><label for="' . $id . '">' . crm_h($label) . '</label><input class="input" id="' . $id . '" name="' . crm_h($name) . '" type="' . crm_h($type) . '" value="' . crm_h($val) . '" ' . $attrs . '></div>'; }
function crm_f_area(string $name, string $label, string $val = '', int $rows = 3): string { $id = 'f_' . preg_replace('/\W+/', '_', $name) . '_' . substr(md5($label), 0, 4); return '<div class="field"><label for="' . $id . '">' . crm_h($label) . '</label><textarea class="input" id="' . $id . '" name="' . crm_h($name) . '" rows="' . $rows . '">' . crm_h($val) . '</textarea></div>'; }
function crm_f_select(string $name, string $label, array $opts, string $sel = '', bool $blank = false): string { $id = 'f_' . preg_replace('/\W+/', '_', $name) . '_' . substr(md5($label), 0, 4); $o = $blank ? '<option value="">—</option>' : ''; foreach ($opts as $k => $l) $o .= '<option value="' . crm_h($k) . '"' . ((string)$k === $sel ? ' selected' : '') . '>' . crm_h($l) . '</option>'; return '<div class="field"><label for="' . $id . '">' . crm_h($label) . '</label><select id="' . $id . '" name="' . crm_h($name) . '">' . $o . '</select></div>'; }
function crm_form(string $act, array $hidden, string $inner, string $btn, string $class = ''): string { $o = '<form method="post" class="crmForm ' . crm_h($class) . '" action="/crm.php">' . crm_csrf_field() . '<input type="hidden" name="act" value="' . crm_h($act) . '">'; foreach ($hidden as $k => $v) $o .= '<input type="hidden" name="' . crm_h($k) . '" value="' . crm_h($v) . '">'; return $o . $inner . '<button class="btn sm">' . crm_h($btn) . '</button></form>'; }
function crm_money_cell($minor, string $cur): string { return crm_h(crm_money_format((int)$minor, $cur)); }
function crm_pct($v): string { return $v === null ? 'not enough data' : $v . '%'; }
function crm_msg_label(string $c): string {
  static $m = ['ok' => 'Saved.', 'forbidden' => 'Your role does not allow that action.', 'transition_invalid' => 'That status change is not allowed from the current status.', 'reason_required' => 'A reason is required.', 'lead_not_qualified' => 'Only a qualified lead can be converted.', 'amount_invalid' => 'Enter a valid amount (up to 2 decimals).', 'currency_invalid' => 'Choose a supported currency.', 'disclosure_label_required' => 'A disclosure label (Sponsored, Advertisement or Partner content) is required before approval.', 'landing_url_required' => 'A safe https landing URL is required before approval.', 'dates_required' => 'Start and end dates are required before scheduling.', 'amount_required_for_won' => 'An amount is required to mark an opportunity won.', 'received_exceeds_invoiced' => 'Received cannot exceed the amount recorded as invoiced.', 'proposal_not_accepted' => 'A contract can only be created from an accepted proposal.', 'personal_data_in_notes' => 'Research notes must not contain email addresses or phone numbers.', 'optout_line_required' => 'The draft must include an opt-out line containing STOP.', 'contact_unsubscribed' => 'That contact has unsubscribed.', 'no_consent_basis' => 'That contact has no consent basis for outreach.', 'evidence_url_required' => 'An https evidence URL is required to list a partner publicly.', 'partner_not_approved' => 'Only an approved partner can be listed.'];
  return $m[$c] ?? 'Not saved: ' . str_replace('_', ' ', $c) . '.';
}

// ---- actions -------------------------------------------------------------------------------------------------------------------------
/** Handles one POST action. @return array{0:string,1:string} [redirect query, result code] */
function crm_handle_action(PDO $pdo, array $u, array $p): array {
  $a = (string)($p['act'] ?? ''); $id = (int)($p['id'] ?? 0); $s = fn($k) => (string)($p[$k] ?? ''); $r = [false, 'unknown_action']; $go = 'v=dashboard';
  switch ($a) {
    case 'lead_assign': $r = crm_lead_assign($pdo, $u, $id, $s('assignee') === '' ? null : (int)$s('assignee')); $go = "v=lead&id=$id"; break;
    case 'lead_qualify': $r = crm_lead_qualify($pdo, $u, $id, ['need' => $s('need'), 'budget' => $s('budget'), 'timeline' => $s('timeline'), 'authority' => $s('authority')], $s('decision'), $s('reason')); $go = "v=lead&id=$id"; break;
    case 'lead_convert': $r = crm_lead_convert($pdo, $u, $id, $s('title'), $s('amount'), $s('currency') ?: 'EUR', $s('close') ?: null); $go = $r[0] ? 'v=opportunity&id=' . (int)$r[1] : "v=lead&id=$id"; break;
    case 'note': $t = $s('etype'); $eid = (int)$s('eid'); $can = crm_can($u['role'], 'write'); $done = $can && crm_activity_add($pdo, $u, $t, $eid, in_array($s('kind'), ['note', 'call', 'meeting', 'reply'], true) ? $s('kind') : 'note', $s('body')); $r = [$done, $done ? 'ok' : ($can ? 'body_required' : 'forbidden')]; if ($done) crm_audit($pdo, $u, 'note_add', $t, $eid, 'note added'); $go = 'v=' . (in_array($t, ['lead', 'opportunity', 'company', 'campaign', 'partner'], true) ? $t : 'dashboard') . '&id=' . $eid; break;
    case 'consult_schedule': $r = crm_consult_schedule($pdo, $u, (int)$s('eid'), $s('when'), (int)($s('minutes') ?: 30), $s('note')); $go = 'v=lead&id=' . (int)$s('eid'); break;
    case 'consult_status': $r = crm_consult_set_status($pdo, $u, $id, $s('to')); $go = 'v=lead&id=' . (int)$s('eid'); break;
    case 'task_add': $r = crm_can($u['role'], 'write') ? crm_task_add($pdo, $u, $s('etype'), (int)$s('eid'), $s('title'), $s('due'), $s('assignee') === '' ? null : (int)$s('assignee')) : [false, 'forbidden']; $go = 'v=' . ($s('back') ?: 'tasks'); break;
    case 'task_done': $r = crm_can($u['role'], 'write') ? [crm_task_done($pdo, $id), 'ok'] : [false, 'forbidden']; $go = 'v=tasks'; break;
    case 'opp_create': $r = crm_opp_create($pdo, $u, (int)$s('company_id'), null, $s('kind'), $s('title'), $s('amount'), $s('currency') ?: 'EUR', $s('close') ?: null); $go = $r[0] ? 'v=opportunity&id=' . (int)$r[1] : 'v=opportunities'; break;
    case 'opp_move': $r = crm_opp_move($pdo, $u, $id, $s('to'), $s('reason')); $go = "v=opportunity&id=$id"; break;
    case 'opp_update': $r = crm_opp_update($pdo, $u, $id, ['title' => $s('title'), 'amount' => $s('amount'), 'currency' => $s('currency'), 'expected_close' => $s('close'), 'owner_id' => $s('owner')]); $go = "v=opportunity&id=$id"; break;
    case 'proposal_create': case 'proposal_revise':
      $rows = []; foreach ((array)($p['item'] ?? []) as $it) if (is_array($it)) $rows[] = $it; $in = ['currency' => $s('currency'), 'discount' => $s('discount'), 'tax' => $s('tax'), 'billing_period' => $s('billing_period'), 'valid_until' => $s('valid_until'), 'terms' => $s('terms'), 'items' => $rows];
      if ($a === 'proposal_create') { $r = crm_proposal_create($pdo, $u, (int)$s('opp'), $in); $go = $r[0] ? 'v=proposal&id=' . (int)$r[1] : 'v=opportunity&id=' . (int)$s('opp'); } else { $r = crm_proposal_revise($pdo, $u, $id, $in); $go = "v=proposal&id=$id"; } break;
    case 'proposal_status': $r = crm_proposal_set_status($pdo, $u, $id, $s('to')); $go = "v=proposal&id=$id"; break;
    case 'contract_create': $r = crm_contract_create($pdo, $u, $id, $s('start'), $s('end') ?: null, $s('renewal') ?: null, $s('auto') === '1'); $go = $r[0] ? 'v=contract&id=' . (int)$r[1] : "v=proposal&id=$id"; break;
    case 'contract_confirm': $r = crm_contract_confirm($pdo, $u, $id); $go = "v=contract&id=$id"; break;
    case 'contract_cancel': $r = crm_contract_cancel($pdo, $u, $id, $s('reason'), $s('effective') ?: null); $go = "v=contract&id=$id"; break;
    case 'contract_renew': $r = crm_contract_renew($pdo, $u, $id, $s('end')); $go = "v=contract&id=$id"; break;
    case 'revenue_record': $r = crm_revenue_record($pdo, $u, $id, $s('kind'), $s('amount'), $s('date'), $s('reference'), $s('note')); $go = "v=contract&id=$id"; break;
    case 'campaign_update': $r = crm_campaign_update($pdo, $u, $id, ['disclosure_label' => $s('label'), 'landing_url' => $s('landing_url'), 'start_date' => $s('start'), 'end_date' => $s('end'), 'placement_notes' => $s('notes'), 'quote' => $s('quote'), 'quote_currency' => $s('quote_currency') ?: 'EUR', 'title' => $s('title')]); $go = "v=campaign&id=$id"; break;
    case 'campaign_move': $r = crm_campaign_move($pdo, $u, $id, $s('to'), $s('reason')); $go = "v=campaign&id=$id"; break;
    case 'partner_move': $r = crm_partner_move($pdo, $u, $id, $s('to'), $s('reason')); $go = "v=partner&id=$id"; break;
    case 'partner_publish': $r = crm_partner_publish($pdo, $u, $id, $s('evidence')); $go = "v=partner&id=$id"; break;
    case 'partner_unpublish': $r = crm_partner_unpublish($pdo, $u, $id); $go = "v=partner&id=$id"; break;
    case 'prospect_add': $r = crm_prospect_add($pdo, $u, $s('company'), $s('website'), $s('kind'), $s('notes'), $s('source_url')); $go = 'v=prospects'; break;
    case 'prospect_fit': $r = crm_prospect_qualify($pdo, $u, $id, $s('fit')); $go = 'v=prospects'; break;
    case 'outreach_draft': $r = crm_outreach_draft_add($pdo, $u, $s('subject'), $s('body'), $s('prospect') === '' ? null : (int)$s('prospect'), $s('contact') === '' ? null : (int)$s('contact')); $go = 'v=outreach'; break;
    case 'outreach_status': $r = crm_outreach_draft_status($pdo, $u, $id, $s('to')); $go = 'v=outreach'; break;
    case 'consent': $r = crm_contact_set_consent($pdo, $u, $id, $s('status'), $s('source')); $go = 'v=company&id=' . (int)$s('company'); break;
    case 'unsubscribe': $r = crm_contact_unsubscribe($pdo, $u, $id); $go = 'v=company&id=' . (int)$s('company'); break;
  }
  return [$go, $r[0] ? 'ok' : (string)$r[1]];
}

// ---- views ---------------------------------------------------------------------------------------------------------------------------
function crm_views(): array { return ['dashboard', 'leads', 'lead', 'opportunities', 'opportunity', 'proposals', 'proposal', 'contracts', 'contract', 'campaigns', 'campaign', 'partners', 'partner', 'prospects', 'outreach', 'companies', 'company', 'tasks', 'audit', 'users']; }
function crm_nav(string $v, array $u): string {
  $items = ['dashboard' => 'Dashboard', 'leads' => 'Leads', 'opportunities' => 'Pipeline', 'proposals' => 'Proposals', 'contracts' => 'Contracts', 'campaigns' => 'Campaigns', 'partners' => 'Partners', 'prospects' => 'Prospects', 'outreach' => 'Outreach drafts', 'companies' => 'Companies', 'tasks' => 'Tasks'] + ($u['role'] === 'owner' ? ['audit' => 'Audit log', 'users' => 'Users'] : []);
  $top = ['lead' => 'leads', 'opportunity' => 'opportunities', 'proposal' => 'proposals', 'contract' => 'contracts', 'campaign' => 'campaigns', 'partner' => 'partners', 'company' => 'companies'][$v] ?? $v;
  $o = '<nav aria-label="CRM sections" class="crmNav" style="display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 16px">'; foreach ($items as $k => $l) $o .= '<a class="btn sm' . ($k === $top ? '' : ' secondary') . '" href="/crm.php?v=' . $k . '"' . ($k === $top ? ' aria-current="page"' : '') . '>' . crm_h($l) . '</a>'; return $o . '</nav>';
}
function crm_tbl(string $caption, array $head, array $rows): string {
  if (!$rows) return '<p class="small">Nothing to show yet.</p>';
  $o = '<div class="tableWrap" tabindex="0" role="region" aria-label="' . crm_h($caption) . ' (scrollable)"><table class="table"><caption class="sr">' . crm_h($caption) . '</caption><thead><tr>'; foreach ($head as $h) $o .= '<th scope="col">' . crm_h($h) . '</th>'; $o .= '</tr></thead><tbody>';
  foreach ($rows as $r) { $o .= '<tr>'; foreach ($r as $c) $o .= '<td>' . $c . '</td>'; $o .= '</tr>'; } return $o . '</tbody></table></div>';
}
function crm_link(string $v, $id, string $text): string { return '<a href="/crm.php?v=' . crm_h($v) . '&amp;id=' . (int)$id . '">' . crm_h($text) . '</a>'; }
function crm_notes_block(PDO $pdo, array $u, string $type, int $id): string {
  $o = '<h3>Notes and history</h3>'; $act = crm_activities($pdo, $type, $id, 50);
  $o .= $act ? '<ul class="small">' . implode('', array_map(fn($a) => '<li><strong>' . crm_h($a['kind']) . '</strong> ' . crm_h($a['created_at']) . ($a['who'] ? ' · ' . crm_h($a['who']) : '') . '<br>' . nl2br(crm_h($a['body'])) . '</li>', $act)) . '</ul>' : '<p class="small">No notes yet.</p>';
  if (crm_can($u['role'], 'write')) $o .= crm_form('note', ['etype' => $type, 'eid' => $id], crm_f_select('kind', 'Type', ['note' => 'Note', 'call' => 'Call', 'meeting' => 'Meeting'] + ($type === 'lead' ? ['reply' => 'E-mail reply sent (counts as response)'] : [])) . crm_f_area('body', 'Add a note (do not paste credentials or card data)'), 'Add note')
    . crm_form('task_add', ['etype' => $type, 'eid' => $id, 'back' => $type . '&id=' . $id], crm_f_input('title', 'Follow-up task') . crm_f_input('due', 'Due (YYYY-MM-DD or YYYY-MM-DD HH:MM)', gmdate('Y-m-d', time() + 3 * 86400)) . crm_f_select('assignee', 'Assignee', array_column(crm_users_list($pdo), 'display_name', 'id'), '', true), 'Add task');
  $t = $pdo->prepare('SELECT t.id, t.title, t.due_at, u.display_name FROM crm_tasks t LEFT JOIN crm_users u ON u.id = t.assignee_id WHERE t.entity_type = ? AND t.entity_id = ? AND t.done_at IS NULL ORDER BY t.due_at'); $t->execute([$type, $id]); $tasks = $t->fetchAll(PDO::FETCH_NUM);
  if ($tasks) { $o .= '<h4>Open follow-ups</h4><ul class="small">'; foreach ($tasks as [$tid, $tt, $due, $who]) $o .= '<li>' . crm_h($tt) . ' · due ' . crm_h($due) . ($who ? ' · ' . crm_h($who) : '') . (crm_can($u['role'], 'write') ? ' ' . crm_form('task_done', ['id' => $tid], '', 'Done', 'inline') : '') . '</li>'; $o .= '</ul>'; }
  return $o;
}

function crm_render_view(PDO $pdo, array $u, string $v, array $q): void {
  $id = (int)($q['id'] ?? 0); $users = array_column(crm_users_list($pdo), 'display_name', 'id'); $canW = crm_can($u['role'], 'write'); $cur = array_combine(crm_currencies(), crm_currencies());
  switch ($v) {
    case 'dashboard':
      $days = (int)($q['days'] ?? 90); if (!in_array($days, [30, 90, 365], true)) $days = 90; $d = crm_dashboard($pdo, $days);
      echo '<h2>Dashboard <span class="small">(last ' . (int)$d['days'] . ' days)</span></h2>';
      if ($d['synthetic_rows'] > 0) echo '<div class="noteBox" role="status"><strong>This database contains synthetic test records (' . (int)$d['synthetic_rows'] . ').</strong> Figures below include them. Never present test figures as real.</div>';
      if (!$d['has_data']) { echo '<p>No inquiries, opportunities or contracts have been recorded yet, so there is nothing to report. Figures appear here only from real records.</p>'; }
      $card = fn($l, $val, $note = '') => '<div class="card"><div class="small">' . crm_h($l) . '</div><div style="font-size:1.6rem;font-weight:700">' . $val . '</div>' . ($note !== '' ? '<div class="small">' . crm_h($note) . '</div>' : '') . '</div>';
      $money = fn(array $m) => $m ? implode('<br>', array_map(fn($c, $x) => crm_money_cell($x, $c), array_keys($m), $m)) : '—';
      echo '<div class="cardGrid">' . $card('New inquiries', (int)$d['inquiries'], 'advertising ' . $d['inquiries_by_kind']['advertising'] . ' · partnership ' . $d['inquiries_by_kind']['partnership'] . ' · development ' . $d['inquiries_by_kind']['development'])
        . $card('Qualified leads', (int)$d['qualified_leads'], 'qualification rate: ' . crm_pct($d['qualification_rate'])) . $card('Lead conversion', crm_pct($d['conversion_rate']), 'leads converted to opportunities')
        . $card('Open opportunities', (int)$d['open_opportunities'], 'unweighted value') . $card('Pipeline value', $money($d['pipeline_value']), 'sum of open opportunities, per currency')
        . $card('Win rate', crm_pct($d['win_rate']), 'won ' . $d['won'] . ' · lost ' . $d['lost']) . $card('Proposal acceptance', crm_pct($d['proposals']['acceptance_rate']), 'of ' . (int)$d['proposals']['decided'] . ' decided proposals')
        . $card('Confirmed MRR', $money($d['mrr']), 'signed, active, recurring contracts') . $card('Confirmed ARR', $money($d['arr']), 'MRR basis; not a forecast') . $card('Follow-up tasks', (int)$d['tasks_open'], (int)$d['tasks_overdue'] . ' overdue') . '</div>';
      echo '<h3>Revenue, by definition (per currency, never mixed)</h3><p class="small">Forecast is a hypothetical planning figure (open value × assumed stage weights). It is not revenue. Invoiced and received are manual records of events outside this system. Recognized uses a simple whole-month schedule.</p>';
      $rows = []; foreach ($d['revenue'] as $c => $r) $rows[] = [crm_h($c), crm_money_cell($r['proposed'], $c), crm_money_cell($r['forecast'], $c) . ' <span class="small">(hypothetical)</span>', crm_money_cell($r['contracted'], $c), crm_money_cell($r['invoiced'], $c), crm_money_cell($r['received'], $c), crm_money_cell($r['recognized'], $c)];
      echo crm_tbl('Revenue by classification', ['Currency', 'Proposed', 'Forecast', 'Contracted', 'Invoiced', 'Received', 'Recognized'], $rows);
      $st = []; foreach ($d['pipeline_by_stage'] as $k => $x) $st[] = [crm_h(crm_stages()[$k]), (int)$x['count'], $money($x['value'])]; echo '<h3>Pipeline</h3>' . crm_tbl('Pipeline by stage', ['Stage', 'Opportunities', 'Value'], $st);
      $src = []; foreach ($d['sources'] as $k => $n) $src[] = [crm_h($k), (int)$n]; echo '<h3>Lead sources</h3>' . crm_tbl('Lead sources', ['Source', 'Leads'], $src);
      $cm = []; foreach ($d['campaign_attribution'] as $k => $n) $cm[] = [crm_h($k), (int)$n]; echo '<h3>Campaign attribution</h3><p class="small">Leads whose landing URL carried the campaign code. Counts only.</p>' . crm_tbl('Campaign attribution', ['Campaign code', 'Attributed leads'], $cm);
      echo '<p class="small">Partners: ' . crm_h(json_encode($d['partners'])) . ' · Campaigns: ' . crm_h(json_encode($d['campaigns'])) . ' · Renewals in 60 days: ' . (int)$d['renewals_60d'] . '</p>'; break;
    case 'leads':
      $f = ['kind' => (string)($q['kind'] ?? ''), 'status' => (string)($q['status'] ?? ''), 'assigned' => (string)($q['assigned'] ?? ''), 'q' => (string)($q['q'] ?? ''), 'response' => (string)($q['response'] ?? ''), 'duplicates' => !empty($q['duplicates']), 'page' => (int)($q['page'] ?? 1)]; $L = crm_leads_list($pdo, $f);
      echo '<h2>Leads</h2><form method="get" action="/crm.php" class="crmForm"><input type="hidden" name="v" value="leads">' . crm_f_input('q', 'Search', $f['q']) . crm_f_select('kind', 'Kind', crm_lead_kinds(), $f['kind'], true) . crm_f_select('status', 'Status', crm_lead_statuses(), $f['status'], true) . crm_f_select('assigned', 'Assigned to', ['none' => 'Unassigned'] + $users, $f['assigned'], true) . '' . crm_f_select('response', 'Response', ['unanswered' => 'Unanswered', 'overdue' => 'Overdue', 'answered' => 'Answered'], $f['response'], true) . '<label><input type="checkbox" name="duplicates" value="1"' . ($f['duplicates'] ? ' checked' : '') . '> Possible duplicates only</label> <button class="btn sm">Filter</button></form>';
