      $mv = array_filter(crm_partner_statuses(), fn($k) => in_array($k, crm_partner_transitions()[$p['status']] ?? [], true) && (in_array($k, ['approved', 'rejected', 'suspended'], true) ? crm_can($u['role'], 'approve') : $canW), ARRAY_FILTER_USE_KEY);
      if ($mv) echo '<h3>Status</h3>' . crm_form('partner_move', ['id' => $id], crm_f_select('to', 'Move to', $mv) . crm_f_input('reason', 'Reason (required to reject or suspend)'), 'Update status');
      if ($p['status'] === 'approved' && crm_can($u['role'], 'approve')) echo '<h3>Public listing</h3>' . ($p['public_listing'] === 'listed' ? crm_form('partner_unpublish', ['id' => $id], '', 'Withdraw public listing') : crm_form('partner_publish', ['id' => $id], crm_f_input('evidence', 'Public https source that verifies this relationship'), 'List publicly'));
      echo crm_notes_block($pdo, $u, 'partner', $id); break;
    case 'prospects':
      echo '<h2>Prospects (research records)</h2><p class="small">Company-level research only. Do not store personal contact details. Nothing is contacted from here.</p>' . crm_tbl('Prospects', ['#', 'Company', 'Kind', 'Fit', 'Source', ''], array_map(fn($x) => [(int)$x['id'], crm_h($x['company_name']) . '<br><span class="small">' . crm_h($x['website']) . '</span>', crm_h(crm_lead_kinds()[$x['kind']] ?? $x['kind']), crm_h(crm_prospect_fit_statuses()[$x['fit_status']] ?? ''), crm_h($x['source_url'] ?: '—'), $canW ? crm_form('prospect_fit', ['id' => $x['id']], crm_f_select('fit', 'Fit', crm_prospect_fit_statuses(), $x['fit_status']), 'Set', 'inline') : ''], crm_prospects_list($pdo)));
      if ($canW) echo '<h3>Add a prospect</h3>' . crm_form('prospect_add', [], crm_f_input('company', 'Company') . crm_f_input('website', 'Website (https://…)') . crm_f_select('kind', 'Kind', crm_lead_kinds()) . crm_f_input('source_url', 'Public source URL') . crm_f_area('notes', 'Research notes (no emails or phone numbers)'), 'Add prospect'); break;
    case 'outreach':
      $rp = crm_outreach_report($pdo); echo '<h2>Outreach drafts</h2><div class="noteBox" role="status">This system does not send outreach. Drafts are for internal planning; “sent” is always ' . (int)$rp['sent'] . '. Contacting a real company needs the owner’s explicit approval and happens outside this system.</div><p class="small">Drafts: ' . (int)$rp['drafts'] . ' · prospects: ' . (int)$rp['prospects'] . ' · unsubscribed contacts: ' . (int)$rp['unsubscribed_contacts'] . ' · open follow-ups: ' . (int)$rp['open_followups'] . '</p>';
      echo crm_tbl('Drafts', ['#', 'Prospect', 'Subject', 'Status', ''], array_map(fn($d) => [(int)$d['id'], crm_h($d['company_name'] ?: ($d['contact_id'] ? 'contact #' . $d['contact_id'] : '—')), crm_h($d['subject']), crm_h($d['status']), crm_can($u['role'], 'outreach') ? crm_form('outreach_status', ['id' => $d['id']], crm_f_select('to', 'Status', ['draft' => 'Draft', 'reviewed' => 'Reviewed', 'archived' => 'Archived'], $d['status']), 'Set', 'inline') : ''], crm_outreach_drafts_list($pdo)));
      if (crm_can($u['role'], 'outreach')) { $tp = crm_outreach_templates()['advertiser_intro']; echo '<h3>New draft</h3><p class="small">Every draft must contain an opt-out line with the word STOP. Example template text is prefilled; edit it before saving.</p>' . crm_form('outreach_draft', [], crm_f_select('prospect', 'Prospect', array_column(crm_prospects_list($pdo), 'company_name', 'id'), '', true) . crm_f_input('contact', 'or Contact id (inbound or opted-in contacts only)') . crm_f_input('subject', 'Subject', $tp['subject']) . crm_f_area('body', 'Body', $tp['body'], 8), 'Save draft'); } break;
    case 'companies':
      echo '<h2>Companies</h2><form method="get" action="/crm.php" class="crmForm"><input type="hidden" name="v" value="companies">' . crm_f_input('q', 'Search', (string)($q['q'] ?? '')) . '<button class="btn sm">Search</button></form>' . crm_tbl('Companies', ['Company', 'Domain', 'Contacts', 'Opportunities', 'Source'], array_map(fn($c) => [crm_link('company', $c['id'], $c['name']), crm_h($c['domain'] ?: '—'), (int)$c['contacts'], (int)$c['opportunities'], crm_h($c['source'] ?: '—')], crm_companies_list($pdo, (string)($q['q'] ?? '')))); break;
    case 'company':
      $c = crm_company_get($pdo, $id); if (!$c) { echo '<p>Company not found.</p>'; break; }
      echo '<h2>' . crm_h($c['name']) . '</h2><p class="small">Domain: ' . crm_h($c['domain'] ?: '—') . ' · source: ' . crm_h($c['source'] ?: '—') . '</p>'; $ct = $pdo->prepare('SELECT * FROM crm_contacts WHERE company_id = ? ORDER BY id'); $ct->execute([$id]);
      echo '<h3>Contacts</h3>'; foreach ($ct->fetchAll(PDO::FETCH_ASSOC) as $k) { echo '<div class="panel"><strong>' . crm_h($k['name']) . '</strong> · ' . crm_h($k['email']) . ' · prefers ' . crm_h($k['contact_pref']) . '<br><span class="small">Consent status: ' . crm_h($k['consent_status']) . ($k['consent_source'] ? ' (' . crm_h($k['consent_source']) . ')' : '') . ($k['unsubscribed_at'] ? ' · UNSUBSCRIBED ' . crm_h($k['unsubscribed_at']) : '') . '. An inbound inquiry only allows replying to that inquiry; it is not marketing consent.</span>';
        if (crm_can($u['role'], 'outreach') && !$k['unsubscribed_at']) echo crm_form('consent', ['id' => $k['id'], 'company' => $id], crm_f_select('status', 'Consent status', ['none' => 'None', 'inbound_inquiry' => 'Inbound inquiry (reply only)', 'opted_in' => 'Opted in'], $k['consent_status']) . crm_f_input('source', 'Where and when consent was given (required for opted-in)', (string)$k['consent_source']), 'Save consent'); if ($canW && !$k['unsubscribed_at']) echo crm_form('unsubscribe', ['id' => $k['id'], 'company' => $id], '', 'Record unsubscribe (final)'); echo '</div>'; }
      echo '<h3>Opportunities</h3>' . crm_tbl('Opportunities', ['#', 'Title', 'Stage', 'Value'], array_map(fn($o) => [crm_link('opportunity', $o['id'], '#' . $o['id']), crm_h($o['title']), crm_h(crm_stages()[$o['stage']]), crm_money_cell($o['amount_minor'], $o['currency'])], $pdo->query('SELECT * FROM crm_opportunities WHERE company_id = ' . (int)$id . ' ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC))) . crm_notes_block($pdo, $u, 'company', $id); break;
    case 'tasks':
      echo '<h2>Follow-up tasks</h2>' . crm_tbl('Open tasks', ['Due', 'Task', 'Linked to', 'Assignee', ''], array_map(fn($t) => [crm_h($t['due_at']) . (strtotime($t['due_at'] . ' UTC') < time() ? ' <span class="badge gray">overdue</span>' : ''), crm_h($t['title']), crm_h($t['entity_type'] . ' #' . $t['entity_id']), crm_h($t['assignee'] ?: '—'), $canW ? crm_form('task_done', ['id' => $t['id']], '', 'Done', 'inline') : ''], crm_tasks_open($pdo, !empty($q['mine']) ? (int)$u['id'] : null))); break;
    case 'audit':
      if (!crm_can($u['role'], 'users')) { echo '<p>Owner only.</p>'; break; } echo '<h2>Audit log</h2><p class="small">Who did what. Summaries never contain email addresses or credentials.</p>' . crm_tbl('Audit log', ['When', 'User', 'Action', 'Entity', 'Summary'], array_map(fn($a) => [crm_h($a['at']), crm_h($a['username']), crm_h($a['action']), crm_h($a['entity_type'] . ($a['entity_id'] ? ' #' . $a['entity_id'] : '')), crm_h($a['summary'])], crm_audit_recent($pdo, 200))); break;
    case 'users':
      if (!crm_can($u['role'], 'users')) { echo '<p>Owner only.</p>'; break; } echo '<h2>Users</h2><p class="small">Users are created and deactivated from the command line (<code>php scripts/crm_user.php</code>), never from the web, so a web compromise cannot create an administrator.</p>' . crm_tbl('Users', ['User', 'Name', 'Role'], array_map(fn($x) => [crm_h($x['username']), crm_h($x['display_name']), crm_h($x['role'])], crm_users_list($pdo))); break;
  }
}
/** Proposal editor: three line-item rows plus totals inputs. */
function crm_proposal_form(string $act, array $hidden, array $items, array $cur, ?array $p = null): string {
  $inner = crm_f_select('currency', 'Currency', $cur, (string)($p['currency'] ?? 'EUR')) . crm_f_select('billing_period', 'Billing', ['one_off' => 'One-off', 'monthly' => 'Monthly', 'annual' => 'Annual'], (string)($p['billing_period'] ?? 'one_off')) . crm_f_input('valid_until', 'Valid until (YYYY-MM-DD)', (string)($p['valid_until'] ?? gmdate('Y-m-d', time() + 30 * 86400))) . crm_f_input('discount', 'Document discount %', $p ? (string)($p['discount_bp'] / 100) : '') . crm_f_input('tax', 'Tax %', $p ? (string)($p['tax_bp'] / 100) : '');
  for ($i = 0; $i < 4; $i++) { $it = $items[$i] ?? null; $inner .= '<fieldset><legend>Line ' . ($i + 1) . '</legend>' . crm_f_input("item[$i][description]", 'Description', (string)($it['description'] ?? '')) . crm_f_input("item[$i][qty]", 'Quantity', $it ? (string)($it['qty_x100'] / 100) : '1') . crm_f_input("item[$i][unit]", 'Unit price', $it ? number_format(intdiv((int)$it['unit_minor'], 100), 0, '.', '') . '.' . str_pad((string)((int)$it['unit_minor'] % 100), 2, '0', STR_PAD_LEFT) : '') . crm_f_input("item[$i][discount]", 'Line discount %', $it ? (string)($it['discount_bp'] / 100) : '') . '</fieldset>'; }
  return crm_form($act, $hidden, $inner . crm_f_area('terms', 'Internal terms / notes', (string)($p['terms'] ?? '')), $act === 'proposal_create' ? 'Create proposal' : 'Save as new version');
}
